package com.governai.audit;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import tools.jackson.databind.JsonNode;import java.time.OffsetDateTime;import java.util.UUID;@Entity @Table(name="audit_event")public class AuditEvent{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="organization_id")private UUID organizationId;@Column(name="decision_request_id")private UUID decisionRequestId;@Column(name="actor_id")private UUID actorId;@Column(name="event_type",nullable=false,length=100)private String eventType;@Column(name="entity_type",length=100)private String entityType;@Column(name="entity_id")private UUID entityId;@JdbcTypeCode(SqlTypes.JSON)@Column(name="previous_state",columnDefinition="jsonb")private JsonNode previousState;@JdbcTypeCode(SqlTypes.JSON)@Column(name="new_state",columnDefinition="jsonb")private JsonNode newState;@JdbcTypeCode(SqlTypes.JSON)@Column(name="event_metadata",columnDefinition="jsonb")private JsonNode eventMetadata;@Column(name="created_at",nullable=false)private OffsetDateTime createdAt;@PrePersist void create(){if(createdAt==null)createdAt=OffsetDateTime.now();}public UUID getId(){return id;}public UUID getOrganizationId(){return organizationId;}public void setOrganizationId(UUID v){organizationId=v;}public UUID getDecisionRequestId(){return decisionRequestId;}public void setDecisionRequestId(UUID v){decisionRequestId=v;}public UUID getActorId(){return actorId;}public void setActorId(UUID v){actorId=v;}public String getEventType(){return eventType;}public void setEventType(String v){eventType=v;}public String getEntityType(){return entityType;}public void setEntityType(String v){entityType=v;}public UUID getEntityId(){return entityId;}public void setEntityId(UUID v){entityId=v;}public JsonNode getPreviousState(){return previousState;}public void setPreviousState(JsonNode v){previousState=v;}public JsonNode getNewState(){return newState;}public void setNewState(JsonNode v){newState=v;}public JsonNode getEventMetadata(){return eventMetadata;}public void setEventMetadata(JsonNode v){eventMetadata=v;}public OffsetDateTime getCreatedAt(){return createdAt;}}
